import{_ as s,a0 as r,w as i,s as d,ao as l,I as n,x as o,a1 as e,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"安卓編年史（7） | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（7） | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（7） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（7） | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/07 - The history of Android","title":"安卓編年史（7）","tag":"The history of Android","desc":""},"relativePath":"The history of Android/07 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/07 - The history of Android.md"};function u(g,t,T,f,h,A){const p=r("Link");return i(),d("div",null,[t[23]||(t[23]=l('<h1 id="安卓編年史-7" tabindex="-1">安卓編年史（7） <a class="header-anchor" href="#安卓編年史-7" aria-label="Permalink to “安卓編年史（7）”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/email2lol.png" alt="電子郵件應用的所有界面。前兩張截圖展示了標籤/收件箱結合的視圖，最後一張截圖展示了一封郵件。"></p><p><em>電子郵件應用的所有界面。前兩張截圖展示了標籤/收件箱結合的視圖，最後一張截圖展示了一封郵件。 [Ron Amadeo供圖]</em></p><p>郵件視圖是——令人驚訝的！居然是白色。安卓的電子郵件應用從歷史角度來説算是個打了折扣的Gmail應用，你可以在這裏看到緊密的聯繫。讀郵件以及寫郵件視圖幾乎沒有任何修改地就從Gmail那裏直接取過來使用。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/IM2.png" alt="即時通訊應用。截圖展示了服務提供商選擇界面，朋友列表，以及一個對話。"></p><p><em>即時通訊應用。截圖展示了服務提供商選擇界面，朋友列表，以及一個對話。[Ron Amadeo供圖]</em></p><p>在Google Hangouts之前，甚至是Google Talk之前，就有了“IM”——安卓1.0帶來的唯一一個即時通訊客户端。令人驚奇的是，它支持多種IM服務：用户可以從AIM，Google Talk，Windows Live Messenger以及Yahoo中挑選。還記得操作系統開發者什麼時候關心過互通性嗎？</p><p>朋友列表是黑色背景界面，如果在聊天中則帶有白色聊天氣泡。狀態用一個帶顏色的圓形來指示，右側的小安卓機器人指示出某人正在使用移動設備。IM應用相比Google Hangouts遠比它有溝通性，這真是十分神奇的。綠色代表着某人正在使用設備並且已經登錄，黃色代表着他們登錄了但處於空閒狀態，紅色代表他們手動設置狀態為忙，不想被打擾，灰色表示離線。現在Hangouts只顯示用户是否打開了應用。</p><p>聊天對話界面明顯基於信息應用，聊天的背景從白色和藍色被換成了白色和綠色。但是沒人更改信息輸入框的顏色，所以加上橙色的高亮效果，界面共使用了白色，綠色，藍色和橙色。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/yt5000.png" alt="安卓1.0上的YouTube。截圖展示了主界面，打開菜單的主界面，分類界面，視頻播放界面。"></p><p><em>安卓1.0上的YouTube。截圖展示了主界面，打開菜單的主界面，分類界面，視頻播放界面。[Ron Amadeo供圖]</em></p><p>以G1的320p屏幕和3G網絡速度，YouTube可能不會有今天這樣的手機上的表現，但谷歌的視頻服務在安卓1.0上就被置入發佈了。主界面看起來就像是安卓市場調整過的版本，頂部帶有一個橫向滾動選擇部分，下面有垂直滾動分類列表。谷歌的一些分類選擇還真是奇怪：“最熱門”和“最多觀看”有什麼區別？</p>',12)),n("p",null,[t[1]||(t[1]=o("這是一個谷歌沒有意識到YouTube最終能達到多龐大的標誌——有一個視頻分類是“最近更新”。在今天，每分鐘有",-1)),e(p,{href:"http://www.youtube.com/yt/press/statistics.html"},{default:a(()=>[...t[0]||(t[0]=[o("100小時時長的視頻",-1)])]),_:1}),t[2]||(t[2]=o("上傳到Youtube上，如果這個分類能正常工作的話，它會是一個快速滾動的視頻列表，快到以至於變為一片無法閲讀的模糊。",-1))]),t[24]||(t[24]=l('<p>菜單含有搜索，喜愛，分類，設置。設置（沒有該圖片）是有史以來最簡陋的，只有個清除搜索歷史的選項。分類都是一樣的平淡，僅僅是個黑色的文本列表。</p><p>最後一張截圖展示了視頻播放界面，只支持橫屏模式。儘管自動隱藏的播放控制有個進度條，但它還是很奇怪地包含了後退和前進按鈕。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/yt3.png" alt="YouTube的視頻菜單，描述頁面，評論。"></p><p><em>YouTube的視頻菜單，描述頁面，評論。[Ron Amadeo供圖]</em></p><p>每個視頻的更多選項可以通過點擊菜單按鈕來打開。在這裏你可以把視頻標記為“喜愛”，查看詳細信息，以及閲讀評論。所有的這些界面，和視頻播放一樣，是鎖定橫屏模式的。</p><p>然而“共享”不會打開一個對話框，它只是向Gmail郵件中加入了視頻的鏈接。想要把鏈接通過短信或即時消息發送給別人是不可能的。你可以閲讀評論，但是沒辦法評價他們或發表自己的評論。你同樣無法給視頻評分或贊。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/camera.png" alt="相機應用的拍照界面，菜單，照片瀏覽模式。"></p><p><em>相機應用的拍照界面，菜單，照片瀏覽模式。[Ron Amadeo供圖]</em></p><p>在實體機上跑真正的安卓意味着相機功能可以正常運作，即便那裏沒什麼太多可關注的。左邊的黑色方塊是相機的界面，原本應該顯示取景器圖像，但SDK的截圖工具沒辦法捕捉下來。G1有個硬件實體的拍照鍵（還記得嗎？），所以相機沒必要有個屏幕上的快門鍵。相機沒有曝光，白平衡，或HDR設置——你可以拍攝照片，僅此而已。</p><p>菜單按鈕顯示兩個選項：跳轉到相冊應用和帶有兩個選項的設置界面。第一個設置選項是是否給照片加上地理標記，第二個是在每次拍攝後顯示提示菜單，你可以在上面右邊看到截圖。同樣的，你目前還只能拍照——還不支持視頻拍攝。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/calviews.png" alt="日曆的月視圖，打開菜單的周視圖，日視圖，以及日程。"></p><p><em>日曆的月視圖，打開菜單的周視圖，日視圖，以及日程。[Ron Amadeo供圖]</em></p><p>就像這個時期的大多數應用一樣，日曆的主命令界面是菜單。菜單用來切換視圖，添加新事件，導航至當天，選擇要顯示的日程，以及打開設置。菜單扮演着每個單獨按鈕的入口的作用。</p><p>月視圖不能顯示約會事件的文字。每個日期旁邊有個側邊，約會會顯示為側邊上的綠色部分，通過位置來表示約會是在一天中的什麼時候。周視圖同樣不能顯示預約文字——G1的320×480的顯示屏像素還不夠密——所以你會在日曆中看到一個帶有顏色指示條的白塊。唯一一個顯示文字的是日程和日視圖。你可以用滑動來切換日期——左右滑動切換周和日，上下滑動切換月份和日程。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/settings.png" alt="設置主界面，無線設置，關於頁面的底部。"></p><p><em>設置主界面，無線設置，關於頁面的底部。[Ron Amadeo供圖]</em></p><p>安卓1.0最終帶來了設置界面。這個界面是個帶有文字的黑白界面，粗略地分為各個部分。每個列表項邊上的下箭頭讓人誤以為點擊它會展開摺疊的更多東西，但是觸摸列表項的任何位置只會加載下一屏幕。所有的界面看起來確實無趣，都差不多一樣，但是嘿，這可是設置啊。</p><p>任何帶有開/關狀態的選項都使用了卡通風格的複選框。安卓1.0最初的複選框真是奇怪——就算是在“未選中”狀態時，它們還是有個灰色的勾選標記在裏面。安卓把勾選標記當作了燈泡，打開時亮起來，關閉的時候變得黯淡，但這不是複選框的工作方式。然而我們最終還是見到了“關於”頁面。安卓1.0運行Linux內核2.6.25版本。</p><p>設置界面意味着我們終於可以打開安全設置並更改鎖屏。安卓1.0只有兩種風格，安卓0.9那樣的灰色方形鎖屏，以及需要你在9個點組成的網格中畫出圖案的圖形解鎖。像這樣的滑動圖案相比PIN碼更加容易記憶和輸入，儘管它沒有增加多少安全性。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/grabbag.png" alt="語音撥號，圖形鎖屏，電池低電量警告，時間設置。"></p><p><em>語音撥號，圖形鎖屏，電池低電量警告，時間設置。[Ron Amadeo供圖]</em></p><p>語音功能和語音撥號一同來到了1.0。這個特性以各種功能實現在AOSP徘徊了一段時間，然而它是一個簡單的撥打號碼和聯繫人的語音命令應用。語音撥號是個和谷歌未來的語音產品完全無關的應用，它的工作方式和非智能機上的語音撥號一樣。</p><p>關於最後一個值得注意的，當電池電量低於百分之十五的時候會觸發低電量彈窗。這是個有趣的圖案，它把電源線錯誤的一端插入手機。谷歌，那可不是（現在依然不是）手機應該有的充電方式。</p><p>安卓1.0是個偉大的開端，但是功能上仍然有許多缺失。強制配備了實體鍵盤和大量硬件按鈕，因為不帶有十字方向鍵或軌跡球的安卓設備依然不被允許銷售。另外，基本的智能手機功能比如自動旋轉依然缺失。內置應用不可能像今天這樣通過安卓市場來更新。所有的谷歌系應用和系統交織在一起。如果谷歌想要升級一個單獨的應用，需要通過運營商推送整個系統的更新。安卓依然還有許多工作要做。</p><h3 id="安卓1-1——第一個真正的增量更新" tabindex="-1">安卓1.1——第一個真正的增量更新 <a class="header-anchor" href="#安卓1-1——第一個真正的增量更新" aria-label="Permalink to “安卓1.1——第一個真正的增量更新”">​</a></h3><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/12/11.png" alt="安卓1.1的所有新特性：語音搜索，安卓市場付費應用支持，谷歌縱橫，設置中的新“系統更新”選項。"></p><p><em>安卓1.1的所有新特性：語音搜索，安卓市場付費應用支持，谷歌縱橫，設置中的新“系統更新”選項。[Ron Amadeo供圖]</em></p>',27)),n("p",null,[t[4]||(t[4]=o("安卓1.0發佈四個半月後，2009年2月，安卓在安卓1.1中得到了它的第一個公開更新。系統方面沒有太多變化，谷歌向1.1中添加的新東西現如今也都已被關閉。谷歌語音搜索是安卓向雲端語音搜索的第一個突擊，它在應用抽屜裏有自己的圖標。儘管這個應用已經不能與谷歌服務器通訊，你可以",-1)),e(p,{href:"http://www.youtube.com/watch?v=y3z7Tw1K17A"},{default:a(()=>[...t[3]||(t[3]=[o("在iPhone上",-1)])]),_:1}),t[5]||(t[5]=o("看到它以前是怎麼工作的。它還沒有語音操作，但你可以説出想要搜索的，結果會顯示在一個簡單的谷歌搜索中。",-1))]),t[25]||(t[25]=n("p",null,"安卓市場添加了對付費應用的支持，但是就像beta客户端中一樣，這個版本的安卓市場已經不能連接Google Play服務器。我們最多能夠看到分類界面，你可以在免費應用、付費應用和全部應用中選擇。",-1)),n("p",null,[t[7]||(t[7]=o("地圖添加了",-1)),e(p,{href:"http://arstechnica.com/information-technology/2009/02/google-tries-location-based-social-networking-with-latitude/"},{default:a(()=>[...t[6]||(t[6]=[o("谷歌縱橫",-1)])]),_:1}),t[8]||(t[8]=o("，一個向朋友分享自己位置的方法。縱橫在幾個月前為了支持Google+而被關閉並且不再能夠工作。地圖菜單裏有個縱橫的選項，但點擊它現在只會打開一個帶載入中圓圈的畫面，並永遠停留在這裏。",-1))]),t[26]||(t[26]=n("p",null,"安卓世界的系統更新來得更加迅速——或者至少是一條在運營商和OEM推送之前獲得更新的途徑——谷歌也在“關於手機”界面添加了檢查系統更新按鈕。",-1)),t[27]||(t[27]=n("hr",null,null,-1)),t[28]||(t[28]=n("p",null,[n("img",{src:"http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg",alt:"Ron Amadeo"})],-1)),n("p",null,[e(p,{href:"http://arstechnica.com/author/ronamadeo"},{default:a(()=>[...t[9]||(t[9]=[o("Ron Amadeo",-1)])]),_:1}),t[10]||(t[10]=o(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1))]),n("p",null,[e(p,{href:"https://twitter.com/RonAmadeo"},{default:a(()=>[...t[11]||(t[11]=[o("@RonAmadeo",-1)])]),_:1})]),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[13]||(t[13]=o("via: ",-1)),e(p,{href:"http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/7/"},{default:a(()=>[...t[12]||(t[12]=[o("http://arstechnica.com/gadgets/2014/06/building-android-a-40000-word-history-of-googles-mobile-os/7/",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("譯者：",-1)),e(p,{href:"https://github.com/alim0x"},{default:a(()=>[...t[14]||(t[14]=[o("alim0x",-1)])]),_:1}),t[17]||(t[17]=o(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:a(()=>[...t[15]||(t[15]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=o("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[18]||(t[18]=[o("LCTT",-1)])]),_:1}),t[21]||(t[21]=o(" 原創翻譯，",-1)),e(p,{href:"http://linux.cn/"},{default:a(()=>[...t[19]||(t[19]=[o("Linux中國",-1)])]),_:1}),t[22]||(t[22]=o(" 榮譽推出",-1))])])}const x=s(m,[["render",u]]);export{y as __pageData,x as default};
